import{_ as a,o as i,a as r,b as o}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMT编程","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/ai_core_simt_programming"},{"text":"原子操作","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/atomic_operations"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simt_programming/atomic_operations.md","filePath":"guide/programming_guide/programming_model/ai_core_simt_programming/atomic_operations.md","outlineHeaders":[{"level":2,"title":"基本语义","slug":"基本语义","link":"#基本语义"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1787050286000}'),t={name:"guide/programming_guide/programming_model/ai_core_simt_programming/atomic_operations.md"};function m(_,e,d,n,g,c){return i(),r("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>原子操作</h1><p>SIMT编程模型中，一个Grid由多个Thread Block组成，每个Thread Block又包含多个Thread。不同Thread可以并发访问同一段Global Memory或Unified Buffer（UB）。当多个线程同时对同一地址执行读-改-写操作时，如果没有同步保护，可能出现数据竞争，导致最终结果不符合预期。</p><p>原子操作用于保证同一地址上的一次读-改-写过程不可被其他线程打断。典型场景包括计数、状态抢占、直方图统计和并行归约等。</p><h2 id="基本语义">基本语义<a class="header-anchor" href="#基本语义">​</a></h2><p>原子操作保证的是单次内存更新的原子性。例如多个线程同时对同一个计数器执行<code>asc_atomic_add</code>时，每次加法都会以原子方式完成，不会出现多个线程读取同一个旧值后覆盖彼此结果的问题。</p><p>原子操作不保证多个线程到达该原子操作的先后顺序，也不是线程同步屏障。多个Thread、Warp或Thread Block同时访问同一地址时，硬件会对这些原子请求进行串行化处理，但串行化顺序通常不由程序指定。</p><p>Ascend C SIMT提供<code>asc_atomic_add</code>、<code>asc_atomic_sub</code>、<code>asc_atomic_cas</code>等原子操作接口，可用于Global Memory或UB中的数据更新。不同接口支持的数据类型、访问空间和返回值约束不同，详细说明请参见<a href="../../../../api/SIMT-API/atomic_operations/atomic_operations_intro.html">原子操作接口</a>。</p><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>仅在确实存在并发写同一地址且需要保证更新不丢失时使用原子操作。</li><li>不要将原子操作等同于线程同步；需要线程到达同一执行点时，应使用同步接口。</li><li>避免大量线程频繁原子更新同一个Global Memory地址，必要时先在Thread Block内做局部聚合。</li><li>不要依赖原子操作返回值表达稳定的线程执行顺序。</li></ul></article></div>',1)])])}const s=a(t,[["render",m]]);export{p as __pageData,s as default};
